def components(g, val=8):
 seen=set(); comps=[]
 for r,row in enumerate(g):
  for c,x in enumerate(row):
   if x==val and (r,c) not in seen:
    st=[(r,c)]; seen.add((r,c)); comp=[]
    while st:
     p=st.pop(); comp.append(p)
     for q in [(p[0]-1,p[1]),(p[0]+1,p[1]),(p[0],p[1]-1),(p[0],p[1]+1)]:
      if 0<=q[0]<len(g) and 0<=q[1]<len(g[0]) and g[q[0]][q[1]]==val and q not in seen: seen.add(q);st.append(q)
    comps.append(comp)
 return sorted(map(len,comps),reverse=True)
